package com.example.starter.invoice.domain;

/**
 * 发票方向：蓝字发票与红字发票。
 */
public enum InvoiceDirection {
    /** 蓝字发票 */
    BLUE,
    /** 红字发票 */
    RED
}

package com.example.starter.invoice.domain;

/**
 * 发票状态：开具→交付→（可红冲）→归档；已全额红冲与已归档均为终态。
 */
public enum InvoiceStatus {
    /** 已开具，待交付 */
    ISSUED,
    /** 已交付，可红冲、可归档 */
    DELIVERED,
    /** 已全额红冲，终态，进一步红冲返回幂等结果 */
    RED_FLUSHED,
    /** 已归档，终态，仅允许红冲 */
    ARCHIVED
}

package com.example.starter.invoice.domain;

/**
 * 红冲类型：全额红冲或按行项目的部分红冲。
 */
public enum RedType {
    /** 全额红冲 */
    FULL,
    /** 部分红冲，仅允许按行项目拆分 */
    PARTIAL
}

package com.example.starter.invoice.domain;

/**
 * 红字信息表状态：待确认→已确认（开具红票）；意见不一致挂起。
 */
public enum InfoStatus {
    /** 待双方确认 */
    PENDING,
    /** 双方已确认并开具红票 */
    CONFIRMED,
    /** 意见不一致，已挂起 */
    SUSPENDED
}

package com.example.starter.invoice.domain;

/**
 * 红字信息表确认方。
 */
public enum Party {
    /** 销方 */
    SELLER,
    /** 购方 */
    BUYER
}

package com.example.starter.invoice.domain;

/**
 * 红字信息表确认意见。
 */
public enum Opinion {
    /** 同意 */
    CONFIRM,
    /** 拒绝 */
    REJECT
}

