 * @param redConfirmedAmount    已确认红票累计金额，单位：元
 * @param availableAmount       可用额度＝总额度−未归档蓝票金额＋已确认红票金额，单位：元
 */
public record CreditAccountResponse(
        String sellerTaxNo,
        BigDecimal totalLimit,
        BigDecimal blueUnarchivedAmount,
        BigDecimal redConfirmedAmount,
        BigDecimal availableAmount) {
}

package com.example.starter.invoice.web;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码与稳定错误码，由全局异常处理器转为统一错误响应。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus status() {
        return status;
    }

    public String code() {
        return code;
    }

    /**
     * 404：资源不存在。
     */
    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, "NOT_FOUND", message);
    }

    /**
     * 409：幂等冲突（同键异参）。
     */
    public static ApiException idempotencyConflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, "IDEMPOTENCY_CONFLICT", message);
    }

    /**
     * 422：业务规则违反（额度不足、状态不允许、红冲超限等）。
     */
    public static ApiException businessRule(String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, "BUSINESS_RULE_VIOLATION", message);
    }
}

package com.example.starter.invoice.web;

/**
 * 统一错误响应体。
 *
 * @param code    稳定错误码
 * @param message 错误描述
 */
public record ErrorResponse(String code, String message) {
}

package com.example.starter.invoice.web;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 全局异常处理：业务异常与参数校验异常转为统一错误响应。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    /**
     * 业务异常。
     */
    @ExceptionHandler(ApiException.class)
    public ResponseEntity<ErrorResponse> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.status())
                .body(new ErrorResponse(ex.code(), ex.getMessage()));
    }

    /**
     * 参数校验失败，返回 400。
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorResponse> handleValidation(MethodArgumentNotValidException ex) {
        String message = ex.getBindingResult().getFieldErrors().stream()
                .findFirst()
                .map(error -> error.getField() + " " + error.getDefaultMessage())
                .orElse("请求参数校验失败");
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorResponse("VALIDATION_FAILED", message));
    }

    /**
     * 请求体不可读（JSON 格式错误等），返回 400。
     */
    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<ErrorResponse> handleNotReadable(HttpMessageNotReadableException ex) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorResponse("VALIDATION_FAILED", "请求体格式错误"));
    }
}

package com.example.starter.invoice.service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.StringJoiner;

/**
 * 幂等指纹工具：对 requestId 与全部业务字段的规范化串计算 SHA-256。
 */
public final class FingerprintUtil {

    private FingerprintUtil() {
    }

    /**
     * 计算指纹。字段按传入顺序以竖线拼接，null 以空串参与。
     */
    public static String fingerprint(String... fields) {
        StringJoiner joiner = new StringJoiner("|");
        for (String field : fields) {
            joiner.add(field == null ? "" : field);
        }
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(joiner.toString().getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalStateException("SHA-256 不可用", e);
        }
    }
}

